import Database from "better-sqlite3";
import fs from "node:fs";
import path from "node:path";

export type Column = "TODO" | "IN_PROGRESS" | "DONE";

export interface Task {
  id: number;
  title: string;
  column: Column;
  position: number;
}

export const COLUMNS: Column[] = ["TODO", "IN_PROGRESS", "DONE"];

const DB_PATH = "/home/user/qwik-app/kanban.db";

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (db) return db;

  const dir = path.dirname(DB_PATH);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  db = new Database(DB_PATH);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");

  db.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      column TEXT NOT NULL CHECK (column IN ('TODO', 'IN_PROGRESS', 'DONE')),
      position INTEGER NOT NULL
    );
  `);

  return db;
}

export function getAllTasks(): Task[] {
  const database = getDb();
  return database
    .prepare(
      `SELECT id, title, column, position FROM tasks ORDER BY column ASC, position ASC`,
    )
    .all() as Task[];
}

export function getTasksByColumn(column: Column): Task[] {
  const database = getDb();
  return database
    .prepare(
      `SELECT id, title, column, position FROM tasks WHERE column = ? ORDER BY position ASC`,
    )
    .all(column) as Task[];
}

export function addTask(title: string): Task {
  const database = getDb();

  const tx = database.transaction((titleValue: string) => {
    const countRow = database
      .prepare(`SELECT COUNT(*) as cnt FROM tasks WHERE column = ?`)
      .get("TODO") as { cnt: number };
    const position = countRow.cnt;

    const info = database
      .prepare(
        `INSERT INTO tasks (title, column, position) VALUES (?, 'TODO', ?)`,
      )
      .run(titleValue, position);

    return {
      id: Number(info.lastInsertRowid),
      title: titleValue,
      column: "TODO" as Column,
      position,
    };
  });

  return tx(title);
}

export interface MoveResult {
  ok: boolean;
  status?: number;
  error?: string;
}

export function moveTask(
  taskId: number,
  targetColumn: string,
  targetPosition: number,
): MoveResult {
  const database = getDb();

  if (!COLUMNS.includes(targetColumn as Column)) {
    return { ok: false, status: 400, error: "Invalid targetColumn" };
  }

  if (
    typeof targetPosition !== "number" ||
    !Number.isInteger(targetPosition) ||
    targetPosition < 0
  ) {
    return { ok: false, status: 400, error: "Invalid targetPosition" };
  }

  const tx = database.transaction(() => {
    const task = database
      .prepare(`SELECT id, title, column, position FROM tasks WHERE id = ?`)
      .get(taskId) as Task | undefined;

    if (!task) {
      return { ok: false, status: 404, error: "Task not found" } as MoveResult;
    }

    const srcColumn = task.column;
    const srcPosition = task.position;
    const destColumn = targetColumn as Column;
    const destPosition = targetPosition;

    if (srcColumn === destColumn) {
      const countRow = database
        .prepare(`SELECT COUNT(*) as cnt FROM tasks WHERE column = ?`)
        .get(srcColumn) as { cnt: number };
      // Max allowed position when staying in same column is count - 1
      if (destPosition > countRow.cnt - 1) {
        return {
          ok: false,
          status: 400,
          error: "targetPosition out of bounds",
        } as MoveResult;
      }

      if (srcPosition === destPosition) {
        return { ok: true } as MoveResult;
      }

      if (srcPosition < destPosition) {
        database
          .prepare(
            `UPDATE tasks SET position = position - 1 WHERE column = ? AND position > ? AND position <= ?`,
          )
          .run(srcColumn, srcPosition, destPosition);
      } else {
        database
          .prepare(
            `UPDATE tasks SET position = position + 1 WHERE column = ? AND position >= ? AND position < ?`,
          )
          .run(srcColumn, destPosition, srcPosition);
      }

      database
        .prepare(`UPDATE tasks SET position = ? WHERE id = ?`)
        .run(destPosition, taskId);
    } else {
      const destCountRow = database
        .prepare(`SELECT COUNT(*) as cnt FROM tasks WHERE column = ?`)
        .get(destColumn) as { cnt: number };
      // After moving, dest column will have destCountRow.cnt + 1 tasks.
      // Valid positions are 0..destCountRow.cnt (inclusive).
      if (destPosition > destCountRow.cnt) {
        return {
          ok: false,
          status: 400,
          error: "targetPosition out of bounds",
        } as MoveResult;
      }

      database
        .prepare(
          `UPDATE tasks SET position = position - 1 WHERE column = ? AND position > ?`,
        )
        .run(srcColumn, srcPosition);

      database
        .prepare(
          `UPDATE tasks SET position = position + 1 WHERE column = ? AND position >= ?`,
        )
        .run(destColumn, destPosition);

      database
        .prepare(`UPDATE tasks SET column = ?, position = ? WHERE id = ?`)
        .run(destColumn, destPosition, taskId);
    }

    return { ok: true } as MoveResult;
  });

  return tx();
}

import { $, component$ } from "@builder.io/qwik";
import {
  Form,
  routeAction$,
  routeLoader$,
  z,
  zod$,
} from "@builder.io/qwik-city";
import { addTask, COLUMNS, getAllTasks, type Column } from "~/lib/db";

export const useTasks = routeLoader$(() => {
  return getAllTasks();
});

export const useAddTask = routeAction$(
  (data) => {
    const title = String(data.title ?? "").trim();
    if (!title) {
      return { success: false as const, error: "Title is required" };
    }
    const task = addTask(title);
    return { success: true as const, task };
  },
  zod$({
    title: z.string(),
  }),
);

const COLUMN_LABELS: Record<Column, string> = {
  TODO: "To Do",
  IN_PROGRESS: "In Progress",
  DONE: "Done",
};

export default component$(() => {
  const tasks = useTasks();
  const addTaskAction = useAddTask();

  return (
    <div class="kanban-board">
      <h1>Kanban Board</h1>

      <Form action={addTaskAction} id="add-task-form" class="add-task-form">
        <input
          type="text"
          name="title"
          placeholder="New task title"
          required
        />
        <button type="submit">Add Task</button>
      </Form>

      <div class="columns">
        {COLUMNS.map((col) => {
          const columnTasks = tasks.value.filter((t) => t.column === col);
          return (
            <div
              key={col}
              class="column"
              data-column={col}
              onDragOver$={(ev: DragEvent) => {
                ev.preventDefault();
              }}
              onDrop$={$(async (ev: DragEvent) => {
                ev.preventDefault();
                const dataTransfer = ev.dataTransfer;
                const taskIdStr = dataTransfer?.getData("text/plain");
                const taskId = Number(taskIdStr);
                if (!taskId) return;

                const targetPosition = columnTasks.length;

                await fetch("/kanban/move", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    taskId,
                    targetColumn: col,
                    targetPosition,
                  }),
                });

                location.reload();
              })}
            >
              <h2>{COLUMN_LABELS[col]}</h2>
              <div class="task-list">
                {columnTasks.map((task) => (
                  <div
                    key={task.id}
                    class="task-item"
                    data-task-id={task.id}
                    draggable
                    onDragStart$={(ev: DragEvent) => {
                      ev.dataTransfer?.setData("text/plain", String(task.id));
                    }}
                  >
                    {task.title}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
});

import type { RequestHandler } from "@builder.io/qwik-city";
import { getAllTasks } from "~/lib/db";

export const onGet: RequestHandler = async (requestEvent) => {
  const tasks = getAllTasks();
  requestEvent.json(200, tasks);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { addTask } from "~/lib/db";

function extractTitle(body: unknown): string | undefined {
  if (body == null) return undefined;

  if (typeof body === "object") {
    // FormData-like or plain object (from JSON / urlencoded / multipart parsing)
    if (typeof (body as any).get === "function") {
      const value = (body as any).get("title");
      return typeof value === "string" ? value : undefined;
    }
    const value = (body as Record<string, unknown>).title;
    return typeof value === "string" ? value : undefined;
  }

  return undefined;
}

export const onPost: RequestHandler = async (requestEvent) => {
  const body = await requestEvent.parseBody();
  const title = extractTitle(body)?.trim();

  if (!title) {
    requestEvent.json(400, { error: "title is required" });
    return;
  }

  const task = addTask(title);
  requestEvent.json(201, task);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { moveTask } from "~/lib/db";

function extractField(body: unknown, key: string): unknown {
  if (body == null) return undefined;

  if (typeof body === "object") {
    if (typeof (body as any).get === "function") {
      return (body as any).get(key);
    }
    return (body as Record<string, unknown>)[key];
  }

  return undefined;
}

export const onPost: RequestHandler = async (requestEvent) => {
  const body = await requestEvent.parseBody();

  const rawTaskId = extractField(body, "taskId");
  const rawTargetColumn = extractField(body, "targetColumn");
  const rawTargetPosition = extractField(body, "targetPosition");

  const taskId = Number(rawTaskId);
  const targetColumn = String(rawTargetColumn ?? "");
  const targetPosition = Number(rawTargetPosition);

  if (!Number.isInteger(taskId) || rawTaskId === undefined) {
    requestEvent.json(404, { error: "Task not found" });
    return;
  }

  if (!Number.isFinite(targetPosition) && rawTargetPosition !== undefined) {
    requestEvent.json(400, { error: "Invalid targetPosition" });
    return;
  }

  const result = moveTask(taskId, targetColumn, targetPosition);

  if (!result.ok) {
    requestEvent.json(result.status ?? 400, { error: result.error });
    return;
  }

  requestEvent.json(200, { success: true });
};

